package client

import "testing"

func TestRedactSensitiveJSON(t *testing.T) {
	input := map[string]any{
		"token":   "abc123456",
		"user":    "user123456",
		"message": "keep visible",
		"nested": []any{
			map[string]any{"client_secret": "secret123456"},
		},
	}

	output := redactSensitiveJSON(input).(map[string]any)
	if output["token"] == "abc123456" {
		t.Fatal("token was not redacted")
	}
	if output["user"] == "user123456" {
		t.Fatal("user key was not redacted")
	}
	if output["message"] != "keep visible" {
		t.Fatalf("message redacted unexpectedly: %v", output["message"])
	}
	nested := output["nested"].([]any)[0].(map[string]any)
	if nested["client_secret"] == "secret123456" {
		t.Fatal("nested secret was not redacted")
	}
}
